@startuml

class Bettor {
  + name : string
  + id : int
  + balance : double
}

class Race {
  + raceId : int
  + startTime : datetime
}

class Runner {
  + horseName : string
  + runnerId : int
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
  + status : string
}

class Winner {
  + winningAmount : double
}

Bettor "1" -- "0..*" Bet : places
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey : riddenBy
Bet "*" -- "1" Race : refersTo
Bet "*" -- "1" Runner : refersTo
Race "1" -- "1" Runner : hasWinner
Runner "1" -- "0..*" Bet : subjectOf
@enduml

